def cancel_duplicate_tasks(apps, schema_editor):
    task = apps.get_model("training", "TrainingTask")
    execution = apps.get_model("training", "TaskExecution")
    database = schema_editor.connection.alias
    active = task.objects.using(database).filter(schedule_slot__isnull=False).exclude(status="cancelled")
    duplicates = list(active.order_by().values("schedule_slot_id").annotate(total=Count("pk")).filter(total__gt=1))
    facts = execution.objects.using(database).filter(training_task_id=OuterRef("pk")).filter(
        Q(started_at__isnull=False)
        | ~Q(status__in=["assigned", "cancelled"])
        | Q(progress_records__isnull=False)
        | Q(state_changes__isnull=False)
        | ~Q(coach_feedback="")
        | Q(feedback_records__isnull=False)
        | Q(attachments__isnull=False)
        | Q(training_logs__isnull=False)
        | Q(completed_at__isnull=False)
        | Q(actual_minutes__isnull=False)
        | ~Q(completion_note="")
        | ~Q(problems="")
        | ~Q(solution="")
        | ~Q(reflection="")
    )
    now = timezone.now()
    for group in duplicates:
        candidates = active.filter(schedule_slot_id=group["schedule_slot_id"]).annotate(
            has_facts=Exists(facts),
            published=models.Case(models.When(status="published", then=True), default=False),
        ).order_by("-has_facts", "-published", "created_at", "pk")
        winner = candidates.values_list("pk", flat=True).first()
        candidates.exclude(pk=winner).update(
            status="cancelled", cancelled_at=now, updated_at=now,
            cancel_reason="每时段单任务迁移，保留任务编号 %s。" % winner,
        )


